 dimensions(s){const r=Math.max(1,Number(s.r)||130),type=s.shape?.type||'circle',value=Number(s.shape?.aspect),aspect=type==='circle'?1:Number.isFinite(value)&&value>0?value:1;return{x:s.x,y:s.y,rx:r*Math.min(1,aspect),ry:r*Math.min(1,1/aspect),type}},
 polygon(shape){const type=shape?.type||'circle';if(type==='freehand')return shape.hand?.points||[];if(type==='rect')return[[-1,-1],[1,-1],[1,1],[-1,1]];if(type==='diamond')return[[0,-1],[1,0],[0,1],[-1,0]];if(type==='rounded'){const p=[],c=.2;for(const[x,y,start]of[[1-c,1-c,0],[-1+c,1-c,90],[-1+c,-1+c,180],[1-c,-1+c,270]])for(let i=0;i<=6;i++){const t=(start+i*15)*Math.PI/180;p.push([x+c*Math.cos(t),y+c*Math.sin(t)])}return p}return Array.from({length:80},(_,i)=>[Math.cos(i*Math.PI/40),Math.sin(i*Math.PI/40)])},
 inside(points,x,y){let yes=false;for(let i=0,j=points.length-1;i<points.length;j=i++){const[a,b]=points[i],[c,d]=points[j],dx=c-a,dy=d-b,t=Math.max(0,Math.min(1,((x-a)*dx+(y-b)*dy)/(dx*dx+dy*dy||1)));if(Math.hypot(x-a-t*dx,y-b-t*dy)<.00001)return true;if((b>y)!==(d>y)&&x<(c-a)*(y-b)/(d-b)+a)yes=!yes}return yes},
 contains(s,p){const d=this.dimensions(s),x=(p.x-s.x)/d.rx,y=(p.y-s.y)/d.ry;if(Math.abs(x)>1.00001||Math.abs(y)>1.00001)return false;if(d.type==='circle'||d.type==='ellipse')return x*x+y*y<=1+1e-10;return this.inside(this.polygon(s.shape),x,y)},
 stroke(points){if(!Array.isArray(points)||points.length<3||points.some(p=>!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite)))throw new Error('请圈出完整区域');const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys),w=x1-x0,h=y1-y0;if(w<72||h<72)throw new Error('请把选区画得再大一点，保留完整的区域');const x=(x0+x1)/2,y=(y0+y1)/2,r=Math.max(w,h)/2,step=Math.max(1,Math.ceil(points.length/768)),p=points.filter((_,i)=>i%step===0||i===points.length-1).map(([a,b])=>[+(2*(a-x)/w).toFixed(6),+(2*(b-y)/h).toFixed(6)]),area=Math.abs(p.reduce((n,[a,b],i)=>{const[c,d]=p[(i+1)%p.length];return n+a*d-c*b},0));if(area<.18){let filled=0;for(let iy=0;iy<32;iy++)for(let ix=0;ix<32;ix++)if(this.inside(p,-1+(ix+.37)/16,-1+(iy+.63)/16))filled++;if(filled<24)throw new Error('请圈出有面积的区域；线段不会变成项目');}const aspect=w/h;return{x,y,r,shape:{type:'freehand',aspect,hand:{aspect,points:p}}}},
 change(s,type,width,height){if(!this.types.includes(type))throw new Error('请选择提供的选区形状');if(type==='freehand'&&!s.shape?.hand?.points?.length)throw new Error('这个选区还没有手绘轮廓，请先重画边界');const old=this.dimensions(s),shape={...(s.shape||{}),type,aspect:type==='circle'?1:type==='freehand'?s.shape.hand.aspect:type==='ellipse'&&old.type==='circle'?1.4:old.rx/old.ry};let r=s.r;if(width!==undefined||height!==undefined){const w=width===undefined?old.rx*2:Number(width),h=height===undefined?old.ry*2:Number(height);if(!Number.isFinite(w)||!Number.isFinite(h)||w<72||h<72||w>2400||h>2400)throw new Error('宽高请保持在72到2400之间');if(type==='circle'&&Math.abs(w-h)>1)throw new Error('圆形宽高相同；可以选择椭圆后分别调整');r=Math.max(w,h)/2;shape.aspect=type==='circle'?1:w/h;}return{...s,r,shape}},
