const RF={redraw:null,layout:new WeakMap()};
function regionSvg(s,group=false){const d=RegionCore.dimensions(s);return`<svg class="region-outline${group?' region-group-outline':''}" viewBox="0 0 ${d.rx*2} ${d.ry*2}" aria-hidden="true"><path d="${RegionCore.path(s)}" fill-rule="evenodd"/></svg>`}
function regionNodes(p,d){const shape=p.space.shape;let grid=RF.layout.get(shape);if(!grid){const polygon=RegionCore.polygon(shape);grid=[];for(let y=-.75;y<=.81;y+=.12)for(let x=-.8;x<=.81;x+=.12)if(RegionCore.inside(polygon,x,y))grid.push([x,y]);RF.layout.set(shape,grid)}const used=[],size=Math.round(Math.min(46,Math.max(25,Math.min(d.rx,d.ry)*.3))),anchor=RegionCore.anchor(shape),members=[p.coordinator,...p.members];return members.map((m,i)=>{let target=i?[anchor[0]+Math.cos(i*2.4)*.62,anchor[1]+.16+Math.sin(i*2.4)*.48]:[anchor[0],Math.min(.3,anchor[1]+.14)];const score=q=>(q[0]-target[0])**2+(q[1]-target[1])**2+used.reduce((n,a)=>n+(Math.hypot((q[0]-a[0])*d.rx,(q[1]-a[1])*d.ry)<size+26?10:0),0);const q=grid.reduce((a,b)=>score(b)<score(a)?b:a,grid[0]||anchor);used.push(q);return memphisNode(p,m,(q[0]+1)*d.rx,(q[1]+1)*d.ry,i?Math.round(size*.8):size,i===0)}).join('')}
const regionProjectBase=memphisProject;memphisProject=function(p){const s=p.space;if(!s.shape||s.shape.type==='circle')return regionProjectBase(p);const d=RegionCore.dimensions(s),selected=state.sel===p.id,hot=linkFrom===p.id;return`<div class="ring region${selected?' sel':''}${hot?' hot':''}" data-pid="${p.id}" data-region-type="${d.type}" style="left:${s.x-d.rx}px;top:${s.y-d.ry}px;width:${d.rx*2}px;height:${d.ry*2}px;--c:${p.ui.color}">${regionSvg(s)}<span class="rt" data-drag="p" title="${esc(p.name)}">${esc(p.name)}</span>${p.summary&&d.ry>90?`<span class="m-sum">${esc(p.summary)}</span>`:''}${regionNodes(p,d)}</div>`};
const regionPlaceBase=placeP;placeP=function(...args){const p=regionPlaceBase(...args);p.space.shape={type:'rounded',aspect:1.25};return p};
hitP=w=>onB(state.projects).slice().reverse().find(p=>RegionCore.contains(p.space,w));
const regionTetherBase=dmTether;dmTether=function(a,b,ra,rb=0){if(!a.shape&&!b.shape)return regionTetherBase(a,b,ra,rb);const u=RegionCore.edge({...a,r:ra},b),v=rb?RegionCore.edge({...b,r:rb},a):b;return`M${u.x} ${u.y} L${v.x} ${v.y}`};
dmHitEndpoint=function(w){const p=hitP(w);if(p)return p.id;const label=document.elementFromPoint(w.x*V().k+V().x,w.y*V().k+V().y)?.closest('.rt,.pc'),id=label?.closest('[data-pid]')?.dataset.pid;if(id&&P(id))return id;const c=dmClusters().slice().reverse().find(c=>RegionCore.contains(c,w));return c?'cluster:'+c.id:null};
function regionApplyStroke(points,name,target){const geometry=RegionCore.stroke(points);if(target){const owner=target.kind==='project'?P(target.id):dmCluster(target.id),object=target.kind==='project'?owner?.space:owner;if(!object)throw new Error('待重画的选区已移除');if(owner.boardId!==state.activeBoard)throw new Error('请回到该选区所在画板再重画');pushUndo();Object.assign(object,geometry);RF.redraw=null;return target.kind==='project'?P(target.id):null}pushUndo();const p=placeP(name,geometry.x,geometry.y);Object.assign(p.space,geometry);return p}
const regionEndBase=endG;endG=function(event,cancel){if(G?.t!=='pen')return regionEndBase(event,cancel);const g=G;G=null;$('#penl').innerHTML='';if(cancel){RF.redraw=null;return}try{const p=regionApplyStroke(g.pts.map(([x,y])=>{const w=toW(x,y);return[w.x,w.y]}),null,RF.redraw);tool='pointer';save();renderAll();if(p)openPan('proj',p.id)}catch(e){hint(e.message||String(e))}};
CAT.push(['project.shape','切换项目选区形状，手绘原形可恢复；仅修改形状，不改变成员或成果','projectId,shape,width?,height?'],['cluster.shape','切换项目组边界形状，保留子项目位置','clusterId,shape,width?,height?'],['project.draw','按给出的画板坐标轨迹创建手绘选区，不自动识别成圆；可视模式使用实际画笔','points,name?,boardId?']);
ACT['project.shape']=a=>{const p=rp(a.projectId),s=RegionCore.change(p.space,a.shape,a.width,a.height);pushUndo();p.space=s;save();return'已切换为'+RegionCore.label(s.shape)+'，可撤销'};
const regionResizeBase=ACT['project.resize'];ACT['project.resize']=a=>{const p=rp(a.projectId);if(!p.space.shape)return regionResizeBase(a);const r=Number(a.r);if(!Number.isFinite(r)||r<36||r>1200)throw new Error('选区整体大小请保持在36到1200之间');pushUndo();p.space.r=r;save();return'已调整选区大小，手绘轮廓保留'};
ACT['cluster.shape']=a=>{const c=fnd(state.clusters,a.clusterId,'项目组'),s=RegionCore.change(c,a.shape,a.width,a.height);pushUndo();Object.assign(c,s);save();return'已修改项目组边界，子项目位置保留'};
