const regionPanBase=renderPan;renderPan=function(){regionPanBase();$('#pan [data-region-settings]')?.remove();const obj=panK==='proj'?P(panId):panK==='cluster'?dmCluster(panId):null;if(!obj)return;const space=panK==='proj'?obj.space:obj;$('#pan').insertAdjacentHTML('beforeend',regionSettings(panK==='proj'?'project':'cluster',obj.id,space));const range=$('#pan [data-dm-radius]');if(range){range.previousElementSibling.textContent='整体大小';range.setAttribute('aria-label','项目选区大小');if(obj.space.shape){range.min='36';range.max='1200';range.value=obj.space.r}}dmDecorate()};
document.addEventListener('change',e=>{const field=e.target;if(field.dataset.regionShape){const[kind,id]=field.dataset.regionShape.split('|');act(kind+'.shape',{[kind==='project'?'projectId':'clusterId']:id,shape:field.value})}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-region-size-form]');if(!form)return;e.preventDefault();e.stopImmediatePropagation();const[kind,id]=form.dataset.regionSizeForm.split('|'),s=kind==='project'?P(id).space:dmCluster(id),width=+form.querySelector('[data-region-size$="|w"]').value,height=s.shape?.type==='circle'||!s.shape?width:+form.querySelector('[data-region-size$="|h"]').value;act(kind+'.shape',{[kind==='project'?'projectId':'clusterId']:id,shape:s.shape?.type||'circle',width,height})},true);

