const regionBoardBase=renderBoard;renderBoard=function(){regionBoardBase();for(const el of document.querySelectorAll('[data-cluster]')){const c=dmCluster(el.dataset.cluster);if(!c?.shape)continue;const d=RegionCore.dimensions(c);el.classList.add('region');el.dataset.regionType=d.type;Object.assign(el.style,{left:c.x-d.rx+'px',top:c.y-d.ry+'px',width:d.rx*2+'px',height:d.ry*2+'px'});el.querySelector(':scope>.region-outline')?.remove();el.insertAdjacentHTML('afterbegin',regionSvg(c,true));}for(const p of onB(state.projects)){const el=$('#L [data-pid="'+p.id+'"]');if(!el)continue;el.dataset.regionType=p.space.shape?.type||'circle';if(p.space.shape&&p.space.shape.type!=='circle'&&state.inbox.some(i=>i.pid===p.id&&!i.done)&&!el.querySelector('.m-inbox'))el.insertAdjacentHTML('beforeend',`<span class="m-inbox">${icon('inbox',13)}新收件</span>`);const handle=el.querySelector('[data-dm-project-resize]');if(handle){handle.setAttribute('aria-label','调整 '+p.name+' 选区大小');handle.title='拖动调整选区大小；双击恢复';if(p.space.shape&&p.space.shape.type!=='circle'){handle.style.right='-7px';handle.style.bottom='-7px'}}}};
